# POST /api/sheets/{sheetId}/people/{personId}/retire — retire a person from a date (blank: the
# sheet's today); a date that is not a date is refused. From the day the sheet's today reaches the
# date, their open claims no statement bound leave every live total (ROLLUP/TOTALS lines when they move).
# A viewer may change nothing: refused before anything is read or written.
guard:
  class: net.officefloor.hq.app.setting.RefuseViewer
  next: validate
validate:
  class: net.officefloor.hq.app.person.ValidateRetire
  next: before
before:
  class: net.officefloor.hq.app.rollup.TakeRollup
  govern: [ transaction ]
  next: load
load:
  class: net.officefloor.hq.app.person.LoadPerson
  govern: [ transaction ]
  next: retire
retire:
  class: net.officefloor.hq.app.person.RetirePerson
  govern: [ transaction ]
  next: audit
audit:
  class: net.officefloor.hq.app.person.RecordPersonRetired
  govern: [ transaction ]
  next: rollup
rollup:
  class: net.officefloor.hq.app.rollup.RecordRollup
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.person.RespondWithPerson
package net.officefloor.hq.app.person;

import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/** Binds the retirement date: null when blank (the sheet's today); a date that is not a date is refused. */
public class ValidateRetire {
    public void validate(@RequestBody RetireRequest request, Out<RetireRequest> body)
            throws InvalidPersonException {
        String from = request == null || request.from() == null ? "" : request.from().trim();
        if (!from.isEmpty()) {
            try {
                LocalDate.parse(from);
            } catch (DateTimeParseException e) {
                throw new InvalidPersonException("Not a date: " + from);
            }
        }
        body.set(new RetireRequest(from.isEmpty() ? null : from));
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Val;

/** Retires the person from the date asked (the sheet's today when none): they count as retired at once. */
public class RetirePerson {
    public void retire(@Val RetireRequest request, @Val Person person, SheetRepository sheets,
            PersonRepository people) {
        person.setRetiredFrom(request.from() != null ? request.from()
                : sheets.today(person.getSheetId()).toString());
        people.updateRetired(person);
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.Audit;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.RequestParam;

/** Last write step: only a retirement that went through is recorded. */
public class RecordPersonRetired {
    public void record(@RequestParam(name = "by", required = false) String by,
            @Val Person person, Audit audit) {
        audit.record("PERSON_RETIRED sheet=" + person.getSheetId() + " by=" + (by == null ? "" : by)
                + " name=" + person.getName() + " from=" + person.getRetiredFrom());
    }
}
